// Targeted personalization iteration; account data and collection hierarchy are unchanged.
const icon=(name)=>`<svg viewBox="0 0 24 24" width="21" height="21" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${{sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',moon:'<path d="M20 15.5A8.5 8.5 0 0 1 8.5 4a8.5 8.5 0 1 0 11.5 11.5Z"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="var(--bg)"/><circle cx="15" cy="17" r="3" fill="var(--bg)"/>',volume:'<path d="M11 5 6 9H3v6h3l5 4V5Zm4 3a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',mute:'<path d="M11 5 6 9H3v6h3l5 4V5Zm5 4 5 6m0-6-5 6"/>'}[name]}</svg>`;
const userName=()=>stored?.profile?.name||stored?.user?.name||'我';
let settingsTab='themes',focusStarted=false,rainDateSeen='',orbitDrag=null,orbitTurn=0,orbitTilt=0,orbitRelease=0,suppressPlanetClick=false;
const oldApply=apply;
apply=function(){oldApply();const p=effective(),dark=document.body.dataset.dark==='true',tint=p.color||THEMES[p.theme].color;document.body.style.setProperty('--bg',`color-mix(in srgb, ${tint} ${dark?'13%':'9%'}, ${dark?'#14171b':'#fbfbf8'})`);document.body.style.setProperty('--surface',`color-mix(in srgb, ${tint} ${dark?'18%':'5%'}, ${dark?'#20242a':'#ffffff'})`);document.body.style.setProperty('--soft',`color-mix(in srgb, ${tint} ${dark?'24%':'15%'}, ${dark?'#272c32':'#f1f2ed'})`);document.body.style.setProperty('--line',`color-mix(in srgb, ${tint} ${dark?'28%':'23%'}, ${dark?'#353941':'#e6e8e3'})`);updateHeader()};
function updateHeader(){const r=$('.header-right');r.innerHTML=`<button class="icon-button" data-v4="daynight" aria-label="${document.body.dataset.dark==='true'?'切换日间模式':'切换夜间模式'}">${icon(document.body.dataset.dark==='true'?'sun':'moon')}</button><button class="icon-button" data-action="settings" aria-label="个性化设置">${icon('settings')}</button>`}
render=function(){apply();view==='home'?home():workspace();dock();enhanceControls()};
function weekIssue(date=new Date()){const d=new Date(Date.UTC(date.getFullYear(),date.getMonth(),date.getDate()));const weekday=d.getUTCDay()||7;d.setUTCDate(d.getUTCDate()+4-weekday);const year=d.getUTCFullYear();return `${year} 年 · 第 ${String(Math.ceil((((d-new Date(Date.UTC(year,0,1)))/86400000)+1)/7)).padStart(2,'0')} 期`}
const POSTERS=[{id:'sea',title:'海风来信',en:'LETTERS FROM THE SEA',desc:'有些答案，藏在潮汐之间。',image:'poster-sea.png'},{id:'night',title:'未眠之城',en:'WHEN THE CITY SLEEPS',desc:'在所有灯熄灭之前，与你相遇。',image:'poster-night.png'},{id:'road',title:'一路向远',en:'THE LONG WAY HOME',desc:'走得更远，是为了回到自己。',image:'poster-road.png'}];
function cinemaComposition(){const p=POSTERS.find(x=>x.id===prefs.poster)||POSTERS[0];return `<div class="cinema-composition film-${p.id}"><div class="film-poster"><img class="poster-photo" src="${p.image}" alt="${p.title}电影海报背景"><div class="poster-top"><span>YIYU PICTURES PRESENTS</span><span>一部由 ${esc(userName())} 创作的日常</span></div><div class="poster-title"><span class="eyebrow">${p.en}</span><h1>${p.title}</h1><p>${p.desc}</p></div><div class="poster-bottom"><span>WRITTEN & DIRECTED BY<br><small>${esc(userName())}</small></span><div>此刻上映 <b data-live-time>${timeText()}</b></div><span class="film-rating">A FILM ABOUT<br>YOUR EVERYDAY</span></div></div><div class="poster-choices" aria-label="电影海报方案">${POSTERS.map((x,i)=>`<button data-poster="${x.id}" class="${p.id===x.id?'selected':''}" aria-pressed="${p.id===x.id}">0${i+1} ${x.title}</button>`).join('')}</div></div>`}
const oldHome=home;
home=function(){oldHome();if(effective().theme==='cinema'){$('.cinema-composition').outerHTML=cinemaComposition();document.body.dataset.poster=prefs.poster||'sea'}if(effective().theme==='paper'){$('.paper-meta>span:nth-child(2)').textContent=weekIssue();$('.paper-bottom').innerHTML=`主编 · ${esc(userName())}<span>YIYU / ${weekIssue()}</span>`}if(effective().theme==='music'){syncMusicUI();$('.record-calibration').textContent=`33⅓ · ${userName()}`};if(effective().theme==='flip'){if(homeTimerMode==='date')$('.flip-face').insertAdjacentHTML('beforeend','<div class="clock-seconds"><span id="clock-seconds"></span><small>SECONDS</small></div>');syncFocusControls()};$('.orbit-hint')?.remove();if(effective().theme==='rain')updateRainDate();tickExtras();enhanceControls()};
function updateRainDate(){const el=$('.rain-date [data-live-date]');if(!el)return;const value=dateText();el.removeAttribute('data-live-date');el.innerHTML=`<span class="rain-calendar">${esc(value)}</span>`;if(value!==rainDateSeen){rainDateSeen=value;if(!matchMedia('(prefers-reduced-motion: reduce)').matches)el.firstChild.animate([{transform:'translateY(-400px)',opacity:0},{transform:'translateY(0)',opacity:1}],{duration:1150,easing:'cubic-bezier(.25,.7,.3,1)'})}}
function syncFocusControls(){const c=$('.focus-controls');if(!c)return;c.innerHTML=`<button class="primary" data-v2="focus-toggle">${focusRunning?'暂停专注':focusStarted?'继续专注':'开始专注'}</button>${focusStarted?'<button data-v2="focus-reset">重置</button>':''}<p>一次，只做一件事。</p>`}
const oldTick=tick;
tick=function(){oldTick();tickExtras()};
function tickExtras(){if($('#clock-seconds'))$('#clock-seconds').textContent=String(new Date().getSeconds()).padStart(2,'0');if($('.rain-date')&&rainDateSeen!==dateText())updateRainDate();if($('.paper-meta>span:nth-child(2)'))$('.paper-meta>span:nth-child(2)').textContent=weekIssue();const bar=$('#music-progress');if(bar)bar.style.width=((audioCtx?audioCtx.currentTime:0)%(TRACKS[trackIndex].beat*64)/(TRACKS[trackIndex].beat*64)*100)+'%'}
function settingsPanel(p){if(settingsTab==='themes')return `<div class="themes theme-gallery">${Object.entries(THEMES).map(([id,t])=>`<button class="theme-tile ${p.theme===id?'selected':''}" data-v2-theme="${id}" aria-pressed="${p.theme===id}"><div class="theme-preview mini-${id}"><span>${t.mini}</span>${id==='music'?'<i class="mini-record"></i>':''}</div><div class="theme-tile-label"><b>${t.name}</b><span>${p.theme===id?'✓':t.en}</span></div></button>`).join('')}</div><section class="setting-section"><h3>明暗模式${inheritLabel('mode')}</h3>${choices('mode',[['light','浅色'],['dark','深色'],['system','跟随系统']],p)}</section><section class="setting-section"><h3>整体配色${inheritLabel('color')}</h3><div class="swatches">${PALETTES.map(([v,n])=>`<button class="swatch ${p.color===v?'selected':''}" style="--swatch:${v}" data-pref="color" data-value="${v}" aria-label="${n}" title="${n}"></button>`).join('')}</div></section>`;if(settingsTab==='type')return `<section class="setting-section"><h3>字体气质${inheritLabel('font')}</h3>${choices('font',[['sans','清晰现代'],['serif','人文书写']],p)}<div class="font-specimen ${p.font}">把喜欢的，留在这里。<small>Make room for what matters.</small></div></section>`;return `<section class="setting-section"><h3>空间页宽度${inheritLabel('width')}</h3>${choices('width',[['safe','舒适留白'],['wide','横向铺开']],p)}<div class="width-specimen ${p.width}"><i></i><i></i><i></i></div></section>`}
renderSettings=function(){const p=scope==='scene'?{...prefs,...overrides[sceneId]}:prefs;$('#settings h2').textContent='个性化设置';$('#settings-body').innerHTML=`${view==='space'?`<div class="segmented"><button data-scope="global" class="${scope==='global'?'selected':''}">全局设置</button><button data-scope="scene" class="${scope==='scene'?'selected':''}">当前场景</button></div>`:''}<p class="scope-note">${scope==='scene'?`仅应用于「${esc(scene().name)}」`:'应用于首页与空间，自定义场景保留独立设置。'}</p><div class="settings-tabs" role="tablist" aria-label="个性化分类">${[['themes','主题与配色'],['type','字体'],['layout','布局']].map(([id,n])=>`<button role="tab" aria-selected="${settingsTab===id}" data-settings-tab="${id}">${n}</button>`).join('')}</div><div class="settings-panel" role="tabpanel">${settingsPanel(p)}</div>${scope==='scene'?'<button class="reset" data-action="reset-scene">恢复跟随全局</button>':''}`;ensureDoneButtons()};
function ensureDoneButtons(){document.querySelectorAll('dialog').forEach(d=>{if(!d.querySelector('.dialog-done')){const footer=document.createElement('div');footer.className='dialog-done';footer.innerHTML='<button type="button" data-action="close">完成</button>';d.append(footer)}})}
const originalShow=show;show=function(id){ensureDoneButtons();originalShow(id);enhanceControls()};const originalQuick=quickSearch;quickSearch=function(){originalQuick();ensureDoneButtons();enhanceControls()};
// Native select remains the source of truth, custom listbox supplies consistent visuals.
let pickerId=0;
function enhanceControls(){document.querySelectorAll('select[data-enhanced]').forEach(s=>{const text=s.parentElement.querySelector('.select-trigger span');if(text)text.textContent=s.selectedOptions[0]?.textContent||'请选择'});document.querySelectorAll('select:not([data-enhanced])').forEach(select=>{select.dataset.enhanced='true';const wrap=document.createElement('div');wrap.className='select-wrap';select.before(wrap);wrap.append(select);select.classList.add('select-source');select.tabIndex=-1;select.setAttribute('aria-hidden','true');const trigger=document.createElement('button');trigger.type='button';trigger.className='select-trigger';trigger.setAttribute('aria-label',select.getAttribute('aria-label')||'选择保存位置');trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');const list=document.createElement('div');list.className='select-options';list.id='picker-'+(++pickerId);list.setAttribute('role','listbox');list.hidden=true;trigger.setAttribute('aria-controls',list.id);const sync=()=>{trigger.innerHTML=`<span>${esc(select.selectedOptions[0]?.textContent||'请选择')}</span><small>⌄</small>`};sync();select.addEventListener('change',sync);function close(){list.hidden=true;trigger.setAttribute('aria-expanded','false')}function open(){document.querySelectorAll('.select-options').forEach(x=>x.hidden=true);list.innerHTML=Array.from(select.options).map(o=>`<button type="button" role="option" aria-selected="${o.selected}" data-value="${esc(o.value)}">${esc(o.textContent)}<span>${o.selected?'✓':''}</span></button>`).join('');list.hidden=false;trigger.setAttribute('aria-expanded','true')};trigger.onclick=e=>{e.stopPropagation();list.hidden?open():close()};trigger.onkeydown=e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();open();list.querySelector('[aria-selected=true]')?.focus()}};list.onclick=e=>{const b=e.target.closest('[data-value]');if(!b)return;select.value=b.dataset.value;select.dispatchEvent(new Event('change',{bubbles:true}));close();trigger.focus()};list.onkeydown=e=>{const opts=[...list.querySelectorAll('button')],i=opts.indexOf(document.activeElement);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();opts[e.key==='Home'?0:e.key==='End'?opts.length-1:(i+(e.key==='ArrowDown'?1:opts.length-1))%opts.length].focus()}if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close();trigger.focus()}};wrap.append(trigger,list)})}
document.addEventListener('click',e=>{if(!e.target.closest('.select-wrap'))document.querySelectorAll('.select-options').forEach(el=>{el.hidden=true;el.parentElement.querySelector('.select-trigger').setAttribute('aria-expanded','false')});const b=e.target.closest('button');if(!b)return;if(b.dataset.v4==='daynight'){const mode=document.body.dataset.dark==='true'?'light':'dark';prefs.mode=mode;if(view==='space'&&overrides[sceneId]?.mode)overrides[sceneId].mode=mode;persist();render()}if(b.dataset.settingsTab){settingsTab=b.dataset.settingsTab;renderSettings()}if(b.dataset.poster){prefs.poster=b.dataset.poster;persist();render()}if(b.dataset.v2==='focus-toggle'){focusStarted=true;syncFocusControls()}if(b.dataset.v2==='focus-reset'){focusStarted=false;syncFocusControls()}setTimeout(enhanceControls,0)});
const previousMusicSync=syncMusicUI;
syncMusicUI=function(){previousMusicSync();tickExtras();const mute=$('[data-v3="audio-mute"]');if(mute)mute.innerHTML=icon(muted?'mute':'volume');if($('.vinyl'))$('.vinyl').style.animationPlayState=playing?'running':'paused';document.querySelectorAll('.equalizer i').forEach(el=>el.style.animationPlayState=playing&&!muted?'running':'paused');const trigger=$('#track-select')?.parentElement.querySelector('.select-trigger span');if(trigger)trigger.textContent=TRACKS[trackIndex].name+' · '+TRACKS[trackIndex].mood;};
const originalGroups=renderGroups;renderGroups=function(){originalGroups();enhanceControls()};
function themedSpace(s,i,theme){if(theme==='cinema')return `<span class="space-film" style="background-image:url('${POSTERS[i%3].image}')"><em>0${i+1}</em><b>${esc(s.name)}</b></span>`;if(theme==='music')return `<span class="space-record" style="--record-color:${['#ae9065','#789386','#7d8aab'][i%3]}"><i></i></span><small>${esc(s.name)}</small>`;if(theme==='cosmos')return `<span class="space-planet" style="--planet-color:${PLANETS[i+1].color}"></span><small>${esc(s.name)}</small>`;return `<span>${s.icon}</span><small>${esc(s.name)}</small>`}
const oldDock=dock;dock=function(){oldDock();const theme=effective().theme;$('.dock-options').classList.add('dock-'+theme);$('.dock-options').innerHTML=data.map((s,i)=>`<button class="space-option" data-space="${s.id}">${themedSpace(s,i,theme)}</button>`).join('')};
// Orbit outlines and bodies share the exact same ellipse, then rotate as a group.
startOrbits=function(){cancelAnimationFrame(orbitFrameId);const container=$('.orbit-system');if(!container)return;container.querySelectorAll('.orbit').forEach(x=>x.remove());const track=document.createElement('div');track.className='orbit-track';container.prepend(track);const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let last=performance.now();function frame(now){if(!container.isConnected)return;const dt=Math.min(60,now-last);last=now;if(!orbitDrag&&now>orbitRelease){orbitTurn*=Math.exp(-dt/650);orbitTilt*=Math.exp(-dt/650)}const rot=-.42+orbitTurn,ry=145*Math.max(.24,Math.cos(orbitTilt)),rx=250;track.style.cssText=`width:${rx*2}px;height:${ry*2}px;left:${307.5-rx}px;top:${242.5-ry}px;transform:rotate(${rot}rad)`;const others=PLANETS.filter(p=>p.id!==centerPlanet);PLANETS.forEach(p=>{const el=container.querySelector(`[data-planet=${p.id}]`),central=p.id===centerPlanet,i=others.indexOf(p),a=(reduced?0:now/1000)*.09+i*Math.PI*2/5,x=Math.cos(a)*rx,y=Math.sin(a)*ry;const target={x:central?307.5:307.5+x*Math.cos(rot)-y*Math.sin(rot),y:central?242.5:242.5+x*Math.sin(rot)+y*Math.cos(rot),size:central?275:p.size};const pos=orbitPositions[p.id]??={...target};pos.x=target.x;pos.y=target.y;pos.size+=(target.size-pos.size)*(reduced?1:1-Math.exp(-dt/120));el.style.width=pos.size+'px';el.style.height=pos.size+'px';el.style.transform=`translate(${pos.x-pos.size/2}px,${pos.y-pos.size/2}px)`;el.style.zIndex=central?'4':Math.sin(a)>0?'6':'2';el.classList.toggle('is-center',central);el.setAttribute('aria-pressed',String(central));el.setAttribute('aria-label',`${p.name}${central?'，当前中心':'，设为中心'}`);if(central)el.querySelector('.planet-surface').style.transform=`rotate(${orbitTurn}rad)`});if(!reduced||orbitDrag||Math.abs(orbitTurn)>.001||Math.abs(orbitTilt)>.001)orbitFrameId=requestAnimationFrame(frame)}orbitRefresh=()=>{cancelAnimationFrame(orbitFrameId);frame(performance.now())};orbitRefresh()};
document.addEventListener('pointerdown',e=>{const body=e.target.closest('.orbit-body.is-center');if(!body)return;orbitDrag={x:e.clientX,y:e.clientY,turn:orbitTurn,tilt:orbitTilt,moved:false,body};body.setPointerCapture(e.pointerId)});
document.addEventListener('pointermove',e=>{if(!orbitDrag)return;const dx=e.clientX-orbitDrag.x,dy=e.clientY-orbitDrag.y;if(Math.abs(dx)+Math.abs(dy)>5)orbitDrag.moved=true;orbitTurn=orbitDrag.turn+dx/100;orbitTilt=orbitDrag.tilt+dy/160;orbitRefresh?.()});
document.addEventListener('pointerup',e=>{if(!orbitDrag)return;suppressPlanetClick=orbitDrag.moved;orbitDrag=null;orbitRelease=performance.now()+900;orbitRefresh?.();setTimeout(()=>suppressPlanetClick=false,0)});
document.addEventListener('pointercancel',()=>{orbitDrag=null;orbitRelease=performance.now();orbitRefresh?.()});
document.addEventListener('click',e=>{if(suppressPlanetClick&&e.target.closest('[data-planet]')){e.preventDefault();e.stopImmediatePropagation()}},true);
ensureDoneButtons();render();



